use openarch_api::Session;
use serde_json::{json,Value};
fn call(s:&mut Session,m:&str,p:Value)->Value{s.handle(m,&p).unwrap_or_else(|e|panic!("{m}: {e}"))}
fn enclosure()->(Session,u64,u64,Vec<u64>){let mut s=Session::new();let info=call(&mut s,"doc_info",json!({}));let level=info["levels"][0]["id"].as_u64().unwrap();let view=info["views"].as_array().unwrap().iter().find(|v|v["level_id"]==level&&v["view_kind"]=="floor_plan").unwrap()["id"].as_u64().unwrap();let mut ids=vec![];for(a,b)in[([0,0],[4000,0]),([4000,0],[4000,5000]),([4000,5000],[0,5000]),([0,5000],[0,0])]{ids.push(call(&mut s,"add_wall",json!({"type_id":info["wall_types"][0]["id"],"level_id":level,"start":a,"end":b,"height_mm":3000}))["id"].as_u64().unwrap());}(s,level,view,ids)}
fn value(s:&mut Session,id:u64,label:&str)->Value{let p=call(s,"describe",json!({"id":id}));p["groups"].as_array().unwrap().iter().flat_map(|g|g["rows"].as_array().unwrap()).find(|r|r["label"]==label).unwrap().clone()}
#[test]
fn rooms_recompute_enclosures_and_keep_unplaced_data(){let(mut s,l,v,w)=enclosure();let id=call(&mut s,"add_room",json!({"level_id":l,"view_id":v,"point":[2000,2500]}))["id"].as_u64().unwrap();assert_eq!(call(&mut s,"plan",json!({"view_id":v}))["rooms"].as_array().unwrap().len(),1);let area=value(&mut s,id,"Area")["raw"].as_f64().unwrap();assert!(area>15.0&&area<20.0,"{area}");assert_eq!(value(&mut s,id,"Volume")["value"],"Not Calculated");call(&mut s,"set_room_settings",json!({"settings":{"boundary":"centre","volumes":true}}));let a=value(&mut s,id,"Area")["raw"].as_f64().unwrap();assert!((a-20.0).abs()<0.002,"{a}");assert!(value(&mut s,id,"Volume")["raw"].as_f64().unwrap()>40.0);let dup=call(&mut s,"add_room",json!({"level_id":l,"point":[1000,1000],"tag":false}))["id"].as_u64().unwrap();assert_eq!(value(&mut s,dup,"Status")["value"],"Redundant");call(&mut s,"unplace_room",json!({"id":id}));assert_eq!(value(&mut s,id,"Status")["value"],"Not Placed");assert_eq!(value(&mut s,dup,"Status")["value"],"Placed");call(&mut s,"patch_room",json!({"id":id,"patch":{"name":"Office","department":"Admin"}}));call(&mut s,"delete",json!({"ids":[w[0]]}));assert_eq!(value(&mut s,dup,"Status")["value"],"Not Enclosed");call(&mut s,"undo",json!({}));assert_eq!(value(&mut s,dup,"Status")["value"],"Placed");assert_eq!(value(&mut s,id,"Name")["value"],"Office");}
#[test]
fn separators_room_schedules_keys_and_round_trip(){let(mut s,l,v,_)=enclosure();call(&mut s,"set_room_separators",json!({"level_id":l,"curves":[{"type":"line","a":{"x":2000,"y":0},"b":{"x":2000,"y":5000}}]}));let left=call(&mut s,"add_room",json!({"level_id":l,"view_id":v,"point":[1000,2000]}))["id"].as_u64().unwrap();let right=call(&mut s,"add_room",json!({"level_id":l,"view_id":v,"point":[3000,2000]}))["id"].as_u64().unwrap();assert_eq!(value(&mut s,right,"Status")["value"],"Placed");assert!(value(&mut s,left,"Area")["raw"].as_f64().unwrap()<10.0);let schedule=call(&mut s,"add_schedule",json!({"category":"Rooms","name":"Room Finishes"}))["id"].as_u64().unwrap();let mut def=call(&mut s,"schedule_table",json!({"id":schedule}))["def"].clone();def["fields"]=json!([{"kind":"instance","name":"Number"},{"kind":"instance","name":"Name"},{"kind":"instance","name":"Area"},{"kind":"instance","name":"Status"}]);def["embedded"]=json!({"category":"Doors","fields":[{"kind":"instance","name":"Mark"}],"itemize":true});call(&mut s,"set_schedule",json!({"id":schedule,"def":def}));let t=call(&mut s,"schedule_table",json!({"id":schedule}));assert_eq!(t["columns"].as_array().unwrap().len(),5);assert!(t["rows"].as_array().unwrap().iter().any(|r|r["ids"].as_array().is_some_and(|a|a.contains(&json!(left)))));let path=std::env::temp_dir().join(format!("openarch-rooms-{}.oab",std::process::id()));call(&mut s,"save",json!({"path":path}));let mut reopened=Session::new();call(&mut reopened,"open",json!({"path":path}));assert_eq!(value(&mut reopened,left,"Status")["value"],"Placed");assert_eq!(call(&mut reopened,"schedule_table",json!({"id":schedule}))["def"]["embedded"]["category"],"Doors");std::fs::remove_file(path).unwrap();}

#[test]
fn room_contents_from_to_keys_and_ifc_spaces_share_live_data(){let(mut s,l,v,_)=enclosure();let info=call(&mut s,"doc_info",json!({}));let wall=call(&mut s,"add_wall",json!({"type_id":info["wall_types"][0]["id"],"level_id":l,"start":[2000,0],"end":[2000,5000],"height_mm":3000}))["id"].as_u64().unwrap();let a=call(&mut s,"add_room",json!({"level_id":l,"view_id":v,"point":[1000,2500]}))["id"].as_u64().unwrap();let b=call(&mut s,"add_room",json!({"level_id":l,"view_id":v,"point":[3000,2500]}))["id"].as_u64().unwrap();call(&mut s,"patch_room",json!({"id":a,"patch":{"name":"West Office"}}));call(&mut s,"patch_room",json!({"id":b,"patch":{"name":"East Office"}}));let ty=info["family_types"].as_array().unwrap().iter().find(|t|t["label"]=="Single-Flush: 820 x 2040").unwrap()["id"].clone();let door=call(&mut s,"place_instance",json!({"type_id":ty,"host_id":wall,"point":[2000,2500]}))["id"].as_u64().unwrap();let from=value(&mut s,door,"From Room: Name")["value"].clone();let to=value(&mut s,door,"To Room: Name")["value"].clone();assert_ne!(from,to);assert!([json!("West Office"),json!("East Office")].contains(&from));call(&mut s,"patch_instance",json!({"id":door,"patch":{"flip_facing":true}}));assert_eq!(value(&mut s,door,"From Room: Name")["value"],to);let key=call(&mut s,"add_schedule",json!({"category":"Rooms","name":"Room Styles","key":true,"key_name":"Room Style"}))["id"].as_u64().unwrap();let mut def=call(&mut s,"schedule_table",json!({"id":key}))["def"].clone();def["fields"]=json!([{"name":"Key Name","kind":"instance"},{"name":"Occupancy","kind":"instance"},{"name":"Floor Finish","kind":"instance"}]);call(&mut s,"set_schedule",json!({"id":key,"def":def}));let row=call(&mut s,"add_key_row",json!({"id":key}))["row"].as_u64().unwrap();call(&mut s,"patch_key_row",json!({"id":key,"row":row,"patch":{"name":"Office","values":{"Occupancy":"Business","Floor Finish":"Carpet"}}}));call(&mut s,"patch_element_keys",json!({"ids":[a,b],"patch":{"keys":{key.to_string():row}}}));assert_eq!(value(&mut s,a,"Floor Finish")["kind"],"ro");assert!(s.handle("patch_room",&json!({"id":a,"patch":{"floor_finish":"Vinyl"}})).is_err());
let schedule=call(&mut s,"add_schedule",json!({"category":"Rooms","name":"IFC_Rooms"}))["id"].as_u64().unwrap();let mut def=call(&mut s,"schedule_table",json!({"id":schedule}))["def"].clone();def["fields"]=json!([{"name":"Number","kind":"instance"},{"name":"Name","kind":"instance"},{"name":"Area","kind":"instance"}]);def["embedded"]=json!({"category":"Doors","fields":[{"name":"From Room: Name","kind":"instance"},{"name":"To Room: Name","kind":"instance"}],"filters":[],"itemize":true});def["ifc"]=json!({"enabled":true});call(&mut s,"set_schedule",json!({"id":schedule,"def":def}));let table=call(&mut s,"schedule_table",json!({"id":schedule}));let child=table["rows"].as_array().unwrap().iter().find(|r|r["embedded"]==true&&r["ids"].as_array().is_some_and(|ids|ids.contains(&json!(door)))).unwrap();assert_eq!(child["cells"][3]["text"],to);let path=std::env::temp_dir().join(format!("openarch-spaces-{}.ifc",std::process::id()));call(&mut s,"export_ifc",json!({"path":path,"schedules":true}));let text=std::fs::read_to_string(&path).unwrap();assert_eq!(text.matches("=IFCSPACE(").count(),2);assert!(text.contains("IFCAREAMEASURE("));assert!(text.contains("IFCPROPERTYSET("));std::fs::remove_file(path).unwrap();}

#[test]
fn bounding_floor_clips_volume_and_room_tag_references_survive_undo(){let(mut s,l,v,_)=enclosure();let info=call(&mut s,"doc_info",json!({}));let id=call(&mut s,"add_room",json!({"level_id":l,"view_id":v,"point":[2000,2500]}))["id"].as_u64().unwrap();call(&mut s,"set_room_settings",json!({"settings":{"boundary":"centre","volumes":true}}));let floor=call(&mut s,"add_floor",json!({"type_id":info["floor_types"][0]["id"],"level_id":l,"points":[[-1000,-1000],[5000,-1000],[5000,6000],[-1000,6000]]}))["id"].as_u64().unwrap();call(&mut s,"patch_floor",json!({"id":floor,"patch":{"offset_mm":2500}}));let thickness=info["floor_types"][0]["thickness_mm"].as_f64().unwrap();let volume=value(&mut s,id,"Volume")["raw"].as_f64().unwrap();let area=value(&mut s,id,"Area")["raw"].as_f64().unwrap();assert!((volume-area*(2500.0-thickness)/1000.0).abs()<0.01,"{volume}");call(&mut s,"patch_floor",json!({"id":floor,"patch":{"room_bounding":false}}));assert!(value(&mut s,id,"Volume")["raw"].as_f64().unwrap()>volume);let tags=call(&mut s,"plan",json!({"view_id":v}))["room_tags"].as_array().unwrap().clone();assert_eq!(tags.len(),1);call(&mut s,"delete",json!({"ids":[id]}));assert!(call(&mut s,"plan",json!({"view_id":v}))["room_tags"].as_array().unwrap().is_empty());call(&mut s,"undo",json!({}));assert_eq!(call(&mut s,"plan",json!({"view_id":v}))["room_tags"][0]["id"],tags[0]["id"]);}
